RRB.load({"id": "ntpc-full-6", "exam": "ntpc", "label": "NTPC UG full mock 6 (100 Q)", "questions": [{"s": "General Awareness", "t": "Economy", "q": "In July 1969, how many major commercial banks were nationalised in India?", "o": ["6", "14", "20", "8"], "a": 1, "e": "On 19 July 1969 the government nationalised 14 major banks; 6 more were nationalised in 1980.", "qh": "जुलाई 1969 में भारत में कितने बड़े वाणिज्यिक बैंकों का राष्ट्रीयकरण किया गया?", "oh": ["6", "14", "20", "8"], "eh": "19 जुलाई 1969 को सरकार ने 14 बड़े बैंकों का राष्ट्रीयकरण किया; 1980 में 6 और बैंक राष्ट्रीयकृत हुए।", "level": "medium"}, {"s": "General Awareness", "t": "Awards", "q": "The Abel Prize 2026, often called the 'Nobel of Mathematics', was awarded to:", "o": ["Terence Tao", "Manjul Bhargava", "Akshay Venkatesh", "Gerd Faltings"], "a": 3, "e": "German mathematician Gerd Faltings (Max Planck Institute for Mathematics, Bonn) won the 2026 Abel Prize for his work in arithmetic geometry, including the proof of the Mordell conjecture.", "qh": "2026 का एबेल पुरस्कार, जिसे अक्सर 'गणित का नोबेल' कहा जाता है, किसे मिला?", "oh": ["टेरेंस ताओ", "मंजुल भार्गव", "अक्षय वेंकटेश", "गर्ड फाल्टिंग्स"], "eh": "जर्मन गणितज्ञ गर्ड फाल्टिंग्स (मैक्स प्लांक गणित संस्थान, बॉन) को अंकगणितीय ज्यामिति के काम, जिसमें मॉर्डेल अनुमान का प्रमाण शामिल है, के लिए 2026 का एबेल पुरस्कार मिला।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "Who founded the Satyashodhak Samaj in 1873?", "o": ["B. R. Ambedkar", "Narayana Guru", "Jyotirao Phule", "Periyar E. V. Ramasamy"], "a": 2, "e": "Jyotirao Phule founded the Satyashodhak Samaj in Pune (1873) to fight caste discrimination.", "qh": "1873 में सत्यशोधक समाज की स्थापना किसने की?", "oh": ["बी. आर. आंबेडकर", "नारायण गुरु", "ज्योतिराव फुले", "पेरियार ई. वी. रामासामी"], "eh": "ज्योतिराव फुले ने 1873 में पुणे में जाति भेदभाव के खिलाफ़ सत्यशोधक समाज बनाया।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "Who was the first Speaker of the Lok Sabha?", "o": ["M. A. Ayyangar", "Hukam Singh", "G. V. Mavalankar", "Sardar Hukam Singh Bhinder"], "a": 2, "e": "Ganesh Vasudev Mavalankar was the first Speaker of the Lok Sabha (1952–56); M. A. Ayyangar succeeded him.", "qh": "लोकसभा के पहले अध्यक्ष कौन थे?", "oh": ["एम. ए. अय्यंगर", "हुकम सिंह", "जी. वी. मावलंकर", "सरदार हुकम सिंह भिंडर"], "eh": "गणेश वासुदेव मावलंकर लोकसभा के पहले अध्यक्ष (1952–56) थे; उनके बाद एम. ए. अय्यंगर बने।", "level": "medium"}, {"s": "General Awareness", "t": "Computer", "q": "In MS Excel, which symbol must every formula begin with?", "o": ["= (equal sign)", "# (hash)", "@ (at sign)", "$ (dollar)"], "a": 0, "e": "Excel treats an entry as a formula only if it starts with '='. The '$' sign is used for absolute cell references.", "qh": "MS Excel में हर फ़ॉर्मूला किस चिह्न से शुरू होना चाहिए?", "oh": ["= (बराबर का चिह्न)", "# (हैश)", "@ (ऐट चिह्न)", "$ (डॉलर)"], "eh": "Excel किसी प्रविष्टि को फ़ॉर्मूला तभी मानता है जब वह '=' से शुरू हो। '$' चिह्न एब्सोल्यूट सेल रेफ़रेंस के लिए होता है।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Night blindness is caused by the deficiency of which vitamin?", "o": ["Vitamin B12", "Vitamin C", "Vitamin A", "Vitamin E"], "a": 2, "e": "Vitamin A is needed to make rhodopsin in the eye; its lack causes night blindness.", "qh": "रतौंधी किस विटामिन की कमी से होती है?", "oh": ["विटामिन B12", "विटामिन C", "विटामिन A", "विटामिन E"], "eh": "आँख में रोडॉप्सिन बनाने के लिए विटामिन A चाहिए; इसकी कमी से रतौंधी होती है।", "level": "easy"}, {"s": "General Awareness", "t": "Geography", "q": "Digboi, the site of India's oldest working oil refinery (1901), is in which state?", "o": ["Assam", "Gujarat", "Maharashtra", "Arunachal Pradesh"], "a": 0, "e": "The Digboi refinery in Tinsukia district, Assam, began operating in 1901.", "qh": "भारत की सबसे पुरानी चालू तेल रिफ़ाइनरी (1901) डिगबोई किस राज्य में है?", "oh": ["असम", "गुजरात", "महाराष्ट्र", "अरुणाचल प्रदेश"], "eh": "असम के तिनसुकिया ज़िले की डिगबोई रिफ़ाइनरी 1901 में शुरू हुई थी।", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "In the Indian Parliament, the period that begins immediately after the Question Hour is popularly called:", "o": ["Golden Hour", "Zero Hour", "Adjournment Hour", "Calling Attention Hour"], "a": 1, "e": "Zero Hour, an Indian innovation from the 1960s, starts at about 12 noon right after Question Hour; members raise urgent matters without prior notice.", "qh": "भारतीय संसद में प्रश्नकाल के ठीक बाद शुरू होने वाले समय को आम तौर पर क्या कहा जाता है?", "oh": ["स्वर्णकाल", "शून्यकाल", "स्थगनकाल", "ध्यानाकर्षण काल"], "eh": "शून्यकाल 1960 के दशक का भारतीय नवाचार है, जो प्रश्नकाल के बाद लगभग दोपहर 12 बजे शुरू होता है; इसमें सदस्य बिना पूर्व सूचना के ज़रूरी मुद्दे उठाते हैं।", "level": "easy"}, {"s": "General Awareness", "t": "Polity", "q": "The President's power to grant pardons, reprieves and remissions of punishment is given in:", "o": ["Article 72", "Article 161", "Article 61", "Article 74"], "a": 0, "e": "Article 72 gives the President the power to pardon; Article 161 gives a similar but narrower power to Governors.", "qh": "राष्ट्रपति को क्षमादान, दंड-स्थगन और सज़ा माफ़ करने की शक्ति किस अनुच्छेद में दी गई है?", "oh": ["अनुच्छेद 72", "अनुच्छेद 161", "अनुच्छेद 61", "अनुच्छेद 74"], "eh": "अनुच्छेद 72 राष्ट्रपति को क्षमादान की शक्ति देता है; अनुच्छेद 161 राज्यपालों को ऐसी ही, पर सीमित, शक्ति देता है।", "level": "tough"}, {"s": "General Awareness", "t": "General Science", "q": "Galvanisation is the process of coating iron with a layer of:", "o": ["Tin", "Copper", "Zinc", "Chromium"], "a": 2, "e": "A zinc coating protects iron from rusting; tin plating is used for food cans.", "qh": "गैल्वनीकरण में लोहे पर किस धातु की परत चढ़ाई जाती है?", "oh": ["टिन", "तांबा", "जस्ता (ज़िंक)", "क्रोमियम"], "eh": "जस्ते की परत लोहे को जंग से बचाती है; टिन की परत खाने के डिब्बों पर चढ़ाई जाती है।", "level": "medium"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Which city hosted the NATO Summit on 7–8 July 2026?", "o": ["Ankara", "The Hague", "Vilnius", "Washington, D.C."], "a": 0, "e": "Türkiye hosted the 2026 NATO Summit in Ankara on 7–8 July 2026. (The Hague hosted 2025, Washington 2024, Vilnius 2023.)", "qh": "7–8 जुलाई 2026 को NATO शिखर सम्मेलन किस शहर में हुआ?", "oh": ["अंकारा", "द हेग", "विलनियस", "वॉशिंगटन डी.सी."], "eh": "तुर्किये ने 7–8 जुलाई 2026 को अंकारा में NATO शिखर सम्मेलन की मेज़बानी की। (2025 में द हेग, 2024 में वॉशिंगटन, 2023 में विलनियस।)", "level": "medium"}, {"s": "General Awareness", "t": "Computer", "q": "Who is known as the 'Father of the Computer'?", "o": ["Charles Babbage", "Alan Turing", "Tim Berners-Lee", "Bill Gates"], "a": 0, "e": "Charles Babbage designed the Analytical Engine in the 1830s, the first design for a general-purpose computer.", "qh": "'कंप्यूटर का जनक' किसे कहा जाता है?", "oh": ["चार्ल्स बैबेज", "एलन ट्यूरिंग", "टिम बर्नर्स-ली", "बिल गेट्स"], "eh": "चार्ल्स बैबेज ने 1830 के दशक में एनालिटिकल इंजन बनाया, जो सामान्य काम के कंप्यूटर का पहला डिज़ाइन था।", "level": "easy"}, {"s": "General Awareness", "t": "History", "q": "The 'Doctrine of Lapse' was introduced by which Governor-General?", "o": ["Lord Wellesley", "Lord Cornwallis", "Lord William Bentinck", "Lord Dalhousie"], "a": 3, "e": "Lord Dalhousie (1848–56) used the Doctrine of Lapse to annex states such as Satara, Jhansi and Nagpur.", "qh": "'व्यपगत का सिद्धांत' (Doctrine of Lapse) किस गवर्नर-जनरल ने लागू किया?", "oh": ["लॉर्ड वेलेज़ली", "लॉर्ड कॉर्नवालिस", "लॉर्ड विलियम बेंटिक", "लॉर्ड डलहौज़ी"], "eh": "लॉर्ड डलहौज़ी (1848–56) ने इस सिद्धांत से सतारा, झाँसी और नागपुर जैसे राज्य मिला लिए।", "level": "tough"}, {"s": "General Awareness", "t": "Static GK", "q": "Which Indian city is known as the 'Silicon Valley of India'?", "o": ["Hyderabad", "Bengaluru", "Pune", "Chennai"], "a": 1, "e": "Bengaluru is called the Silicon Valley of India because of its large IT industry.", "qh": "किस भारतीय शहर को 'भारत की सिलिकॉन वैली' कहा जाता है?", "oh": ["हैदराबाद", "बेंगलुरु", "पुणे", "चेन्नई"], "eh": "बड़े IT उद्योग की वजह से बेंगलुरु को भारत की सिलिकॉन वैली कहा जाता है।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Mawsynram, one of the wettest places on Earth, is in which state?", "o": ["Meghalaya", "Assam", "Mizoram", "Sikkim"], "a": 0, "e": "Mawsynram, near Cherrapunji in the Khasi Hills of Meghalaya, records one of the highest average annual rainfalls in the world.", "qh": "धरती की सबसे ज़्यादा बारिश वाली जगहों में से एक, मासिनराम, किस राज्य में है?", "oh": ["मेघालय", "असम", "मिज़ोरम", "सिक्किम"], "eh": "मेघालय की खासी पहाड़ियों में चेरापूंजी के पास मासिनराम में दुनिया की सबसे ज़्यादा औसत सालाना बारिश में से एक होती है।", "level": "easy"}, {"s": "General Awareness", "t": "Polity", "q": "Under which Article can the President promulgate an ordinance when Parliament is not in session?", "o": ["Article 213", "Article 110", "Article 72", "Article 123"], "a": 3, "e": "Article 123 gives the President ordinance-making power; Article 213 gives the same power to a Governor.", "qh": "संसद का सत्र न चलने पर राष्ट्रपति किस अनुच्छेद के तहत अध्यादेश जारी कर सकते हैं?", "oh": ["अनुच्छेद 213", "अनुच्छेद 110", "अनुच्छेद 72", "अनुच्छेद 123"], "eh": "अनुच्छेद 123 राष्ट्रपति को अध्यादेश जारी करने की शक्ति देता है; अनुच्छेद 213 यही शक्ति राज्यपाल को देता है।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "'Operation Flood' is associated with an increase in the production of:", "o": ["Fish", "Milk", "Oilseeds", "Eggs"], "a": 1, "e": "Operation Flood (from 1970), led by Verghese Kurien through NDDB, made India the world's largest milk producer.", "qh": "'ऑपरेशन फ़्लड' किसके उत्पादन में बढ़ोतरी से जुड़ा है?", "oh": ["मछली", "दूध", "तिलहन", "अंडे"], "eh": "वर्गीज़ कुरियन के नेतृत्व में NDDB के ऑपरेशन फ़्लड (1970 से) ने भारत को दुनिया का सबसे बड़ा दूध उत्पादक बनाया।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "The Ghadar Party, formed in 1913 to overthrow British rule, was founded mainly by Indians living in:", "o": ["Japan", "South Africa", "Germany", "USA and Canada"], "a": 3, "e": "Lala Har Dayal and Sohan Singh Bhakna founded the Ghadar Party at San Francisco in 1913, among Indian (mostly Punjabi) migrants in the USA and Canada.", "qh": "1913 में ब्रिटिश राज को उखाड़ फेंकने के लिए बनी ग़दर पार्टी की स्थापना मुख्य रूप से कहाँ रहने वाले भारतीयों ने की थी?", "oh": ["जापान", "दक्षिण अफ़्रीका", "जर्मनी", "अमेरिका और कनाडा"], "eh": "लाला हरदयाल और सोहन सिंह भकना ने 1913 में सैन फ़्रांसिस्को में अमेरिका और कनाडा में बसे भारतीयों (ज़्यादातर पंजाबी) के बीच ग़दर पार्टी बनाई।", "level": "medium"}, {"s": "General Awareness", "t": "Sports", "q": "At the 2026 Asian Games in Aichi-Nagoya, which Indian shooter won the women's trap gold, India's first individual Asian Games trap title in 48 years?", "o": ["Manu Bhaker", "Rajeshwari Kumari", "Neeru Dhanda", "Shreyasi Singh"], "a": 2, "e": "Neeru Dhanda won women's trap gold at Aichi-Nagoya 2026 (Games held 19 Sep–4 Oct 2026; India 85 medals, 4th). The previous individual trap gold was Randhir Singh's in 1978.", "qh": "2026 के आइची-नागोया एशियाई खेलों में किस भारतीय निशानेबाज़ ने महिला ट्रैप का स्वर्ण जीता, जो 48 साल बाद भारत का पहला व्यक्तिगत ट्रैप खिताब था?", "oh": ["मनु भाकर", "राजेश्वरी कुमारी", "नीरू ढांडा", "श्रेयसी सिंह"], "eh": "नीरू ढांडा ने आइची-नागोया 2026 (19 सितंबर–4 अक्टूबर 2026; भारत 85 पदक, चौथा स्थान) में महिला ट्रैप स्वर्ण जीता। पिछला व्यक्तिगत ट्रैप स्वर्ण 1978 में रणधीर सिंह ने जीता था।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "The SI unit of electric charge is:", "o": ["Ampere", "Volt", "Ohm", "Coulomb"], "a": 3, "e": "Charge is measured in coulomb (C); 1 C = 1 ampere × 1 second.", "qh": "विद्युत आवेश का SI मात्रक क्या है?", "oh": ["एम्पियर", "वोल्ट", "ओम", "कूलॉम"], "eh": "आवेश कूलॉम (C) में मापा जाता है; 1 C = 1 एम्पियर × 1 सेकंड।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "Which of these is a direct tax?", "o": ["Goods and Services Tax", "Income tax", "Customs duty", "Excise duty"], "a": 1, "e": "Income tax is paid directly by the person on whom it is levied; GST, customs and excise are indirect taxes.", "qh": "इनमें से कौन-सा प्रत्यक्ष कर है?", "oh": ["वस्तु एवं सेवा कर", "आयकर", "सीमा शुल्क", "उत्पाद शुल्क"], "eh": "आयकर वही व्यक्ति सीधे भरता है जिस पर यह लगता है; GST, सीमा शुल्क और उत्पाद शुल्क अप्रत्यक्ष कर हैं।", "level": "easy"}, {"s": "General Awareness", "t": "Railways", "q": "In which year were the first electric train services in India started, between Bombay VT and Kurla?", "o": ["1853", "1947", "1925", "1961"], "a": 2, "e": "India's first electric train ran between Bombay Victoria Terminus and Kurla on 3 February 1925.", "qh": "भारत में पहली इलेक्ट्रिक ट्रेन सेवा, बॉम्बे VT और कुर्ला के बीच, किस साल शुरू हुई?", "oh": ["1853", "1947", "1925", "1961"], "eh": "भारत की पहली इलेक्ट्रिक ट्रेन 3 फ़रवरी 1925 को बॉम्बे विक्टोरिया टर्मिनस और कुर्ला के बीच चली।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "The Jharia coalfield, a major source of coking coal, is in which state?", "o": ["Odisha", "Chhattisgarh", "West Bengal", "Jharkhand"], "a": 3, "e": "Jharia in Dhanbad district, Jharkhand, is India's main source of prime coking coal.", "qh": "कोकिंग कोयले का बड़ा स्रोत झरिया कोयला क्षेत्र किस राज्य में है?", "oh": ["ओडिशा", "छत्तीसगढ़", "पश्चिम बंगाल", "झारखंड"], "eh": "झारखंड के धनबाद ज़िले का झरिया भारत में प्राइम कोकिंग कोयले का मुख्य स्रोत है।", "level": "medium"}, {"s": "General Awareness", "t": "Static GK", "q": "National Engineers' Day, observed on 15 September in India, marks the birth anniversary of:", "o": ["A. P. J. Abdul Kalam", "Homi J. Bhabha", "C. V. Raman", "M. Visvesvaraya"], "a": 3, "e": "Sir M. Visvesvaraya, the engineer behind the Krishna Raja Sagara dam, was born on 15 September 1861.", "qh": "भारत में 15 सितंबर को मनाया जाने वाला राष्ट्रीय अभियंता दिवस किसकी जयंती है?", "oh": ["ए. पी. जे. अब्दुल कलाम", "होमी जे. भाभा", "सी. वी. रमन", "एम. विश्वेश्वरैया"], "eh": "कृष्णराज सागर बाँध बनाने वाले इंजीनियर सर एम. विश्वेश्वरैया का जन्म 15 सितंबर 1861 को हुआ था।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "The Lucknow Pact of 1916 was an agreement between the Indian National Congress and:", "o": ["All India Muslim League", "Hindu Mahasabha", "Swaraj Party", "Justice Party"], "a": 0, "e": "In the Lucknow Pact (December 1916) the Congress and the Muslim League agreed on joint demands for self-government, including separate electorates.", "qh": "1916 का लखनऊ समझौता भारतीय राष्ट्रीय कांग्रेस और किसके बीच हुआ था?", "oh": ["अखिल भारतीय मुस्लिम लीग", "हिंदू महासभा", "स्वराज पार्टी", "जस्टिस पार्टी"], "eh": "लखनऊ समझौते (दिसंबर 1916) में कांग्रेस और मुस्लिम लीग स्वशासन की साझा माँगों, जिनमें अलग निर्वाचक मंडल भी था, पर सहमत हुए।", "level": "tough"}, {"s": "General Awareness", "t": "Sports", "q": "The term 'Checkmate' is associated with which game?", "o": ["Carrom", "Billiards", "Chess", "Bridge"], "a": 2, "e": "Checkmate ends a chess game: the king is under attack and has no legal escape.", "qh": "'चेकमेट' शब्द किस खेल से जुड़ा है?", "oh": ["कैरम", "बिलियर्ड्स", "शतरंज", "ब्रिज"], "eh": "शतरंज में राजा पर हमला हो और बचने की कोई चाल न हो तो उसे चेकमेट कहते हैं और खेल खत्म हो जाता है।", "level": "medium"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Which Indian site was inscribed on the UNESCO World Heritage List in July 2026, becoming India's 45th World Heritage Site?", "o": ["Moidams of Charaideo", "Maratha Military Landscapes", "Ancient Buddhist Site of Sarnath", "Santiniketan"], "a": 2, "e": "The World Heritage Committee (48th session, Busan) inscribed the Ancient Buddhist Site of Sarnath, Varanasi, in July 2026. Moidams (2024), Maratha Military Landscapes (2025) and Santiniketan (2023) were listed earlier.", "qh": "जुलाई 2026 में किस भारतीय स्थल को यूनेस्को विश्व धरोहर सूची में शामिल किया गया, जिससे वह भारत का 45वाँ विश्व धरोहर स्थल बना?", "oh": ["चराइदेव के मोइदाम", "मराठा सैन्य परिदृश्य", "सारनाथ का प्राचीन बौद्ध स्थल", "शांतिनिकेतन"], "eh": "विश्व धरोहर समिति (48वाँ सत्र, बुसान) ने जुलाई 2026 में वाराणसी के सारनाथ के प्राचीन बौद्ध स्थल को सूची में जोड़ा। मोइदाम (2024), मराठा सैन्य परिदृश्य (2025) और शांतिनिकेतन (2023) पहले जुड़े थे।", "level": "medium"}, {"s": "General Awareness", "t": "Awards", "q": "The Shanti Swarup Bhatnagar Prize, given by CSIR, recognises outstanding work in:", "o": ["Sports", "Science and technology", "Literature", "Social service"], "a": 1, "e": "Named after CSIR's founder-director, the Bhatnagar Prize has honoured young Indian scientists since 1958.", "qh": "CSIR द्वारा दिया जाने वाला शांति स्वरूप भटनागर पुरस्कार किस क्षेत्र में उत्कृष्ट काम के लिए है?", "oh": ["खेल", "विज्ञान और प्रौद्योगिकी", "साहित्य", "समाज सेवा"], "eh": "CSIR के संस्थापक-निदेशक के नाम पर यह पुरस्कार 1958 से युवा भारतीय वैज्ञानिकों को दिया जाता है।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Which is the highest mountain peak lying entirely within India?", "o": ["Nanda Devi", "Kangchenjunga", "Kamet", "Trisul"], "a": 0, "e": "Nanda Devi (7,816 m, Uttarakhand) is the highest peak wholly inside India; Kangchenjunga (8,586 m) lies on the India–Nepal border.", "qh": "पूरी तरह भारत के अंदर स्थित सबसे ऊँची पर्वत चोटी कौन-सी है?", "oh": ["नंदा देवी", "कंचनजंगा", "कामेट", "त्रिशूल"], "eh": "नंदा देवी (7,816 m, उत्तराखंड) पूरी तरह भारत में स्थित सबसे ऊँची चोटी है; कंचनजंगा (8,586 m) भारत–नेपाल सीमा पर है।", "level": "tough"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Warli painting, which uses simple circles, triangles and lines, is a tribal art of which state?", "o": ["Bihar", "Maharashtra", "Odisha", "Madhya Pradesh"], "a": 1, "e": "Warli art comes from the Warli tribe of Palghar/Thane in Maharashtra.", "qh": "गोल, त्रिकोण और रेखाओं वाली वारली चित्रकला किस राज्य की जनजातीय कला है?", "oh": ["बिहार", "महाराष्ट्र", "ओडिशा", "मध्य प्रदेश"], "eh": "वारली कला महाराष्ट्र के पालघर/ठाणे की वारली जनजाति की है।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Who led the Bardoli Satyagraha of 1928?", "o": ["Mahatma Gandhi", "Rajendra Prasad", "Jawaharlal Nehru", "Vallabhbhai Patel"], "a": 3, "e": "Vallabhbhai Patel led the Bardoli peasants against a tax hike in 1928; the women of Bardoli gave him the title 'Sardar'.", "qh": "1928 के बारडोली सत्याग्रह का नेतृत्व किसने किया?", "oh": ["महात्मा गांधी", "राजेंद्र प्रसाद", "जवाहरलाल नेहरू", "वल्लभभाई पटेल"], "eh": "1928 में वल्लभभाई पटेल ने लगान बढ़ोतरी के खिलाफ़ बारडोली के किसानों का नेतृत्व किया; यहीं की महिलाओं ने उन्हें 'सरदार' की उपाधि दी।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "The writ of 'Habeas Corpus' is issued mainly to:", "o": ["Stop a lower court from exceeding its powers", "Produce a detained person before the court", "Direct an official to perform a public duty", "Question a person's right to hold a public office"], "a": 1, "e": "Habeas Corpus ('to have the body') protects against unlawful detention. Prohibition, Mandamus and Quo Warranto match the other options.", "qh": "'बंदी प्रत्यक्षीकरण' (Habeas Corpus) रिट मुख्य रूप से किसलिए जारी की जाती है?", "oh": ["निचली अदालत को अधिकार से बाहर जाने से रोकने के लिए", "हिरासत में लिए व्यक्ति को अदालत के सामने पेश करने के लिए", "किसी अधिकारी को सार्वजनिक कर्तव्य निभाने का निर्देश देने के लिए", "किसी व्यक्ति के सार्वजनिक पद पर बने रहने के अधिकार को चुनौती देने के लिए"], "eh": "बंदी प्रत्यक्षीकरण गैरकानूनी हिरासत से बचाता है। बाकी विकल्प प्रतिषेध, परमादेश और अधिकार-पृच्छा रिट के हैं।", "level": "medium"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Who succeeded General Anil Chauhan as India's Chief of Defence Staff (CDS) in 2026?", "o": ["General Upendra Dwivedi", "Admiral Dinesh K. Tripathi", "Air Chief Marshal A. P. Singh", "Lt. Gen. N. S. Raja Subramani (Retd.)"], "a": 3, "e": "The government named Lt. Gen. N. S. Raja Subramani (Retd.) as the next CDS on 9 May 2026; General Anil Chauhan's tenure ended on 30 May 2026.", "qh": "2026 में जनरल अनिल चौहान के बाद भारत के चीफ़ ऑफ़ डिफ़ेंस स्टाफ़ (CDS) कौन बने?", "oh": ["जनरल उपेंद्र द्विवेदी", "एडमिरल दिनेश के. त्रिपाठी", "एयर चीफ़ मार्शल ए. पी. सिंह", "लेफ्टिनेंट जनरल एन. एस. राजा सुब्रमणि (सेवानिवृत्त)"], "eh": "सरकार ने 9 मई 2026 को लेफ्टिनेंट जनरल एन. एस. राजा सुब्रमणि (सेवानिवृत्त) को अगला CDS नियुक्त किया; जनरल अनिल चौहान का कार्यकाल 30 मई 2026 को खत्म हुआ।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Bronze is an alloy of copper and:", "o": ["Zinc", "Tin", "Nickel", "Lead"], "a": 1, "e": "Bronze = copper + tin; brass = copper + zinc.", "qh": "काँसा (ब्रॉन्ज़) तांबे और किस धातु की मिश्रधातु है?", "oh": ["जस्ता", "टिन", "निकल", "सीसा"], "eh": "काँसा = तांबा + टिन; पीतल = तांबा + जस्ता।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "The Hampi ruins in Karnataka belong to which empire?", "o": ["Chola Empire", "Bahmani Sultanate", "Vijayanagara Empire", "Maratha Empire"], "a": 2, "e": "Hampi was the capital of the Vijayanagara Empire (14th–16th century).", "qh": "कर्नाटक के हम्पी के खंडहर किस साम्राज्य के हैं?", "oh": ["चोल साम्राज्य", "बहमनी सल्तनत", "विजयनगर साम्राज्य", "मराठा साम्राज्य"], "eh": "हम्पी विजयनगर साम्राज्य (14वीं–16वीं सदी) की राजधानी था।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "In October 2026, the RBI's Monetary Policy Committee raised the repo rate by 25 basis points to:", "o": ["5.25%", "6.00%", "6.50%", "5.50%"], "a": 3, "e": "On 7 October 2026 the MPC raised the repo rate from 5.25% to 5.50%, its first hike in nearly four years, and changed its stance to 'calibrated tightening'.", "qh": "अक्टूबर 2026 में RBI की मौद्रिक नीति समिति ने रेपो रेट 25 बेसिस पॉइंट बढ़ाकर कितना कर दिया?", "oh": ["5.25%", "6.00%", "6.50%", "5.50%"], "eh": "7 अक्टूबर 2026 को MPC ने रेपो रेट 5.25% से बढ़ाकर 5.50% किया, जो लगभग चार साल में पहली बढ़ोतरी थी।", "level": "tough"}, {"s": "General Awareness", "t": "Science & Tech", "q": "India's first semiconductor Assembly, Test and Packaging (ATMP) facility, inaugurated by PM Modi in February 2026, belongs to which company?", "o": ["Micron Technology", "Intel", "Samsung", "Texas Instruments"], "a": 0, "e": "Micron's ATMP plant at Sanand, Gujarat, opened on 28 February 2026 and shipped India's first made-in-India memory modules.", "qh": "फ़रवरी 2026 में प्रधानमंत्री मोदी द्वारा उद्घाटित भारत की पहली सेमीकंडक्टर असेंबली, टेस्ट और पैकेजिंग (ATMP) यूनिट किस कंपनी की है?", "oh": ["माइक्रॉन टेक्नोलॉजी", "इंटेल", "सैमसंग", "टेक्सास इंस्ट्रूमेंट्स"], "eh": "माइक्रॉन की साणंद (गुजरात) ATMP यूनिट 28 फ़रवरी 2026 को शुरू हुई और इसने पहले मेड-इन-इंडिया मेमोरी मॉड्यूल भेजे।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "Which Article of the Constitution directs the State to separate the judiciary from the executive?", "o": ["Article 48", "Article 50", "Article 51", "Article 39"], "a": 1, "e": "Article 50, a Directive Principle, asks the State to separate the judiciary from the executive in public services.", "qh": "संविधान का कौन-सा अनुच्छेद राज्य को न्यायपालिका को कार्यपालिका से अलग करने का निर्देश देता है?", "oh": ["अनुच्छेद 48", "अनुच्छेद 50", "अनुच्छेद 51", "अनुच्छेद 39"], "eh": "नीति निदेशक तत्व वाला अनुच्छेद 50 राज्य से लोक सेवाओं में न्यायपालिका को कार्यपालिका से अलग करने को कहता है।", "level": "tough"}, {"s": "General Awareness", "t": "Geography", "q": "Silent Valley National Park, known for its tropical evergreen forest, is in which state?", "o": ["Karnataka", "Tamil Nadu", "Goa", "Kerala"], "a": 3, "e": "Silent Valley in Palakkad district, Kerala, was saved from a hydro project in the 1980s and declared a national park in 1984.", "qh": "उष्णकटिबंधीय सदाबहार वन के लिए प्रसिद्ध साइलेंट वैली राष्ट्रीय उद्यान किस राज्य में है?", "oh": ["कर्नाटक", "तमिलनाडु", "गोवा", "केरल"], "eh": "केरल के पलक्कड़ ज़िले की साइलेंट वैली को 1980 के दशक में एक पनबिजली परियोजना से बचाया गया और 1984 में राष्ट्रीय उद्यान घोषित किया गया।", "level": "medium"}, {"s": "General Awareness", "t": "Science & Tech", "q": "Which Indian space mission made India the first country to reach Mars orbit in its first attempt?", "o": ["Chandrayaan-1", "Aditya-L1", "Astrosat", "Mangalyaan (Mars Orbiter Mission)"], "a": 3, "e": "The Mars Orbiter Mission, launched in November 2013, entered Mars orbit on 24 September 2014.", "qh": "किस भारतीय अंतरिक्ष मिशन से भारत पहले ही प्रयास में मंगल की कक्षा में पहुँचने वाला पहला देश बना?", "oh": ["चंद्रयान-1", "आदित्य-L1", "एस्ट्रोसैट", "मंगलयान (मार्स ऑर्बिटर मिशन)"], "eh": "नवंबर 2013 में छोड़ा गया मार्स ऑर्बिटर मिशन 24 सितंबर 2014 को मंगल की कक्षा में पहुँचा।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "Naveen starts a business with ₹30,000. After 6 months, Rahul joins with ₹36,000. At the end of the year the profit is ₹12,000. What is Rahul's share?", "o": ["₹6,000", "₹7,500", "₹4,500", "₹6,500"], "a": 2, "e": "Capital × months = 30000×12 : 36000×6 = 5 : 3. Share = 3/8 × ₹12,000 = ₹4,500.", "qh": "नवीन ₹30,000 से कारोबार शुरू करता है। 6 महीने बाद राहुल ₹36,000 लेकर जुड़ता है। साल के आखिर में लाभ ₹12,000 है। राहुल का हिस्सा कितना है?", "oh": ["₹6,000", "₹7,500", "₹4,500", "₹6,500"], "eh": "पूँजी × महीने = 30000×12 : 36000×6 = 5 : 3। हिस्सा = 3/8 × ₹12,000 = ₹4,500।", "level": "easy"}, {"s": "Mathematics", "t": "Trigonometry", "q": "If tan θ = 8/15, what is the value of (sin θ + cos θ)/(cos θ − sin θ)?", "o": ["23/7", "17/23", "7/23", "30/7"], "a": 0, "e": "Divide by cos θ: (tan θ + 1)/(1 − tan θ) = (8/15 + 1)/(1 − 8/15) = 23/7.", "qh": "अगर tan θ = 8/15 है, तो (sin θ + cos θ)/(cos θ − sin θ) का मान क्या है?", "oh": ["23/7", "17/23", "7/23", "30/7"], "eh": "cos θ से भाग दें: (tan θ + 1)/(1 − tan θ) = (8/15 + 1)/(1 − 8/15) = 23/7।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "₹1,400 is divided among Karan, Ajay and Arjun in the ratio 1 : 2 : 4. What is Ajay's share?", "o": ["₹800", "₹600", "₹400", "₹1,000"], "a": 2, "e": "Total parts = 7; one part = ₹1,400/7 = ₹200; share = 2 × ₹200 = ₹400.", "qh": "₹1,400 को करण, अजय और अर्जुन में 1 : 2 : 4 के अनुपात में बाँटा गया। अजय का हिस्सा कितना है?", "oh": ["₹800", "₹600", "₹400", "₹1,000"], "eh": "कुल भाग = 7; एक भाग = ₹1,400/7 = ₹200; हिस्सा = 2 × ₹200 = ₹400।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "Find the total number of positive divisors of 108.", "o": ["14", "8", "4", "12"], "a": 3, "e": "108 = 2^2 × 3^3; number of factors = (2+1) × (3+1) = 12.", "qh": "108 के कुल धनात्मक भाजकों की संख्या बताइए।", "oh": ["14", "8", "4", "12"], "eh": "108 = 2^2 × 3^3; गुणनखंडों की संख्या = (2+1) × (3+1) = 12।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "18 men working 6 hours a day can complete a work in 20 days. In how many days will 20 men working 9 hours a day complete the same work?", "o": ["18 days", "12 days", "100/3 days", "10 days"], "a": 1, "e": "M₁D₁H₁ = M₂D₂H₂ → 18 × 20 × 6 = 20 × D × 9 → D = 12 days.", "qh": "18 आदमी रोज़ 6 घंटे काम करके एक काम 20 दिन में पूरा करते हैं। 20 आदमी रोज़ 9 घंटे काम करके वही काम कितने दिन में पूरा करेंगे?", "oh": ["18 दिन", "12 दिन", "100/3 दिन", "10 दिन"], "eh": "M₁D₁H₁ = M₂D₂H₂ → 18 × 20 × 6 = 20 × D × 9 → D = 12 दिन।", "level": "tough"}, {"s": "Mathematics", "t": "Interest", "q": "At what rate of simple interest per annum will a sum of money become four times itself in 20 years?", "o": ["30%", "17%", "15%", "1.25%"], "a": 2, "e": "Interest = 3 × P = P × R × 20/100 → R = 300/20 = 15%.", "qh": "साधारण ब्याज की किस वार्षिक दर से कोई धनराशि 20 साल में चार गुनी हो जाएगी?", "oh": ["30%", "17%", "15%", "1.25%"], "eh": "ब्याज = 3 × P = P × R × 20/100 → R = 300/20 = 15%।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "What is the smallest 3-digit number which, when divided by 5, 6 and 8, leaves a remainder of 3 in each case?", "o": ["120", "3", "123", "243"], "a": 2, "e": "LCM = 120. The required number is a multiple of 120 plus 3: 120 + 3 = 123.", "qh": "3 अंकों की वह सबसे छोटी संख्या कौन-सी है जिसे 5, 6 और 8 से भाग देने पर हर बार 3 शेष बचे?", "oh": ["120", "3", "123", "243"], "eh": "LCM = 120। चाहिए: 120 का गुणज + 3: 120 + 3 = 123।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A shopkeeper gives a discount of 20% on the marked price of a pressure cooker and still makes a profit of 10%. If its cost price is ₹2,640, what is the marked price?", "o": ["₹3,630", "₹3,690", "₹3,590", "₹3,432"], "a": 0, "e": "SP = ₹2,640 × 110/100 = ₹2,904; MP = SP × 100/80 = ₹3,630.", "qh": "एक दुकानदार एक प्रेशर कुकर के अंकित मूल्य पर 20% छूट देता है और फिर भी 10% लाभ कमाता है। अगर इसका क्रय मूल्य ₹2,640 है, तो अंकित मूल्य क्या है?", "oh": ["₹3,630", "₹3,690", "₹3,590", "₹3,432"], "eh": "विक्रय मूल्य = ₹2,640 × 110/100 = ₹2,904; अंकित मूल्य = विक्रय मूल्य × 100/80 = ₹3,630।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "What is the value of 24² − 12²?", "o": ["432", "430", "864", "442"], "a": 0, "e": "a² − b² = (a + b)(a − b) = 36 × 12 = 432.", "qh": "24² − 12² का मान क्या है?", "oh": ["432", "430", "864", "442"], "eh": "a² − b² = (a + b)(a − b) = 36 × 12 = 432।", "level": "easy"}, {"s": "Mathematics", "t": "Mensuration", "q": "What is the volume of a cylinder with radius 3.5 cm and height 12 cm? (Take π = 22/7)", "o": ["231 cm³", "484 cm³", "462 cm³", "924 cm³"], "a": 2, "e": "πr²h = 22/7 × 3.5² × 12 = 462 cm³.", "qh": "3.5 cm त्रिज्या और ऊँचाई 12 cm वाले बेलन का आयतन कितना है? (π = 22/7 लें)", "oh": ["231 cm³", "484 cm³", "462 cm³", "924 cm³"], "eh": "πr²h = 22/7 × 3.5² × 12 = 462 cm³।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "The monthly salaries of Sunita and Amit are in the ratio 5 : 7. If each gets a raise of ₹3,000, the ratio becomes 4 : 5. What is Sunita's present salary?", "o": ["₹2,000", "₹5,000", "₹8,000", "₹10,000"], "a": 1, "e": "(5x + 3000)/(7x + 3000) = 4/5 → 25x − 28x = 12000 − 15000 → x = 1000; salary = 5 × 1000 = ₹5,000.", "qh": "सुनीता और अमित के मासिक वेतन का अनुपात 5 : 7 है। अगर दोनों का वेतन ₹3,000 बढ़े, तो अनुपात 4 : 5 हो जाता है। सुनीता का वर्तमान वेतन क्या है?", "oh": ["₹2,000", "₹5,000", "₹8,000", "₹10,000"], "eh": "(5x + 3000)/(7x + 3000) = 4/5 → 25x − 28x = 12000 − 15000 → x = 1000; वेतन = 5 × 1000 = ₹5,000।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "Find the smallest 5-digit number that leaves no remainder when divided by 14, 21 and 28.", "o": ["10080", "10164", "10094", "10332"], "a": 0, "e": "LCM(14, 21, 28) = 84. The smallest 5-digit multiple of 84 is 10080.", "qh": "5 अंकों की वह सबसे छोटी संख्या बताइए जिसे 14, 21 और 28 से भाग देने पर कोई शेष न बचे।", "oh": ["10080", "10164", "10094", "10332"], "eh": "LCM(14, 21, 28) = 84। 84 का 5 अंकों वाला सबसे छोटी गुणज 10080 है।", "level": "easy"}, {"s": "Mathematics", "t": "Geometry", "q": "What is each interior angle of a regular polygon with 15 sides?", "o": ["2340°", "24°", "156°", "166°"], "a": 2, "e": "Interior angle = 180° − 360°/15 = 156°.", "qh": "15 भुजाओं वाले सम बहुभुज का हर अंदरूनी कोण कितना होता है?", "oh": ["2340°", "24°", "156°", "166°"], "eh": "अंदरूनी कोण = 180° − 360°/15 = 156°।", "level": "medium"}, {"s": "Mathematics", "t": "Algebra", "q": "If x + 1/x = 7, what is the value of x⁴ + 1/x⁴?", "o": ["2399", "2207", "2209", "2401"], "a": 1, "e": "x² + 1/x² = 49 − 2 = 47; x⁴ + 1/x⁴ = 47² − 2 = 2207.", "qh": "अगर x + 1/x = 7 है, तो x⁴ + 1/x⁴ का मान क्या है?", "oh": ["2399", "2207", "2209", "2401"], "eh": "x² + 1/x² = 49 − 2 = 47; x⁴ + 1/x⁴ = 47² − 2 = 2207।", "level": "tough"}, {"s": "Mathematics", "t": "Percentage", "q": "A number is increased by 40%, then decreased by 10%. The result is 15750. What was the original number?", "o": ["12500", "13750", "11875", "15750"], "a": 0, "e": "Original × 1.26 = 15750 → original = 15750 ÷ 1.26 = 12500.", "qh": "एक संख्या को पहले 40% बढ़ाया, फिर 10% घटाया। नतीजा 15750 आया। मूल संख्या क्या थी?", "oh": ["12500", "13750", "11875", "15750"], "eh": "मूल संख्या × 1.26 = 15750 → मूल संख्या = 15750 ÷ 1.26 = 12500।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A seller suffers a loss of 12% when he sells a pressure cooker for ₹1,584. What should the selling price be to make a profit of 8%?", "o": ["₹1,944", "₹1,994", "₹1,800", "₹1,945"], "a": 0, "e": "CP = ₹1,584 × 100/88 = ₹1,800; required SP = ₹1,800 × 108/100 = ₹1,944.", "qh": "एक प्रेशर कुकर ₹1,584 में बेचने पर विक्रेता को 12% हानि होती है। 8% लाभ कमाने के लिए विक्रय मूल्य क्या होना चाहिए?", "oh": ["₹1,944", "₹1,994", "₹1,800", "₹1,945"], "eh": "क्रय मूल्य = ₹1,584 × 100/88 = ₹1,800; ज़रूरी विक्रय मूल्य = ₹1,800 × 108/100 = ₹1,944।", "level": "tough"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A train running at 36 km/h crosses a pole in 8 seconds. What is the length of the train?", "o": ["288 m", "160 m", "103.68 m", "80 m"], "a": 3, "e": "36 km/h = 36 × 5/18 = 10 m/s. Length = 10 × 8 = 80 m.", "qh": "36 km/h की रफ़्तार से चल रही एक ट्रेन एक खंभे को 8 सेकंड में पार करती है। ट्रेन की लंबाई कितनी है?", "oh": ["288 m", "160 m", "103.68 m", "80 m"], "eh": "36 km/h = 36 × 5/18 = 10 m/s। लंबाई = 10 × 8 = 80 m।", "level": "easy"}, {"s": "Mathematics", "t": "Algebra", "q": "The cost of 5 pens and 5 notebooks is ₹280, and the cost of 1 pen and 3 notebooks is ₹136. What is the cost of one notebook?", "o": ["₹42", "₹40", "₹37", "₹56"], "a": 1, "e": "5p + 5n = 280, 1p + 3n = 136. Eliminating p: n = (5×136 − 1×280)/(5×3 − 1×5) = ₹40; pen = ₹16.", "qh": "5 पेन और 5 कॉपियों का दाम ₹280 है, और 1 पेन और 3 कॉपियों का दाम ₹136 है। एक कॉपी का दाम कितना है?", "oh": ["₹42", "₹40", "₹37", "₹56"], "eh": "5p + 5n = 280, 1p + 3n = 136। p हटाने पर: n = (5×136 − 1×280)/(5×3 − 1×5) = ₹40; पेन = ₹16।", "level": "easy"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 7 consecutive numbers is 56. What is the smallest of them?", "o": ["59", "63", "53", "54"], "a": 2, "e": "The average is the middle number 56; there are 3 numbers on each side with gap 1 → smallest = 53.", "qh": "7 लगातार संख्याओं का औसत 56 है। उनमें सबसे छोटी संख्या कौन-सी है?", "oh": ["59", "63", "53", "54"], "eh": "औसत ही बीच वाली संख्या 56 है; दोनों ओर 3 संख्याएँ, अंतर 1 → उत्तर = 53।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "Amit can finish a work in 10 days and Vikas in 15 days. In how many days can they finish it working together?", "o": ["7 days", "12.5 days", "6 days", "5 days"], "a": 2, "e": "Work per day together = 1/10 + 1/15 = 1/6 → time = 6 days.", "qh": "अमित एक काम 10 दिन में और विकास 15 दिन में पूरा कर सकता है। दोनों मिलकर वह काम कितने दिन में करेंगे?", "oh": ["7 दिन", "12.5 दिन", "6 दिन", "5 दिन"], "eh": "साथ में एक दिन का काम = 1/10 + 1/15 = 1/6 → समय = 6 दिन।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A ceiling fan was sold for ₹720, which gave the seller a loss of 25%. How much had the seller paid for it?", "o": ["₹920", "₹960", "₹900", "₹1,010"], "a": 1, "e": "CP = SP × 100/75 = ₹720 × 100/75 = ₹960.", "qh": "एक छत का पंखा ₹720 में बिका, जिससे विक्रेता को 25% हानि हुआ। विक्रेता ने इसके लिए कितने रुपये दिए थे?", "oh": ["₹920", "₹960", "₹900", "₹1,010"], "eh": "क्रय मूल्य = विक्रय मूल्य × 100/75 = ₹720 × 100/75 = ₹960।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 2 1/4 × 3 2/5 ÷ 1 1/2", "o": ["5.1", "10.2", "5.6", "10/51"], "a": 0, "e": "Convert to improper fractions: 9/4, 17/5, 3/2. Working step by step gives 5.1.", "qh": "सरल कीजिए: 2 1/4 × 3 2/5 ÷ 1 1/2", "oh": ["5.1", "10.2", "5.6", "10/51"], "eh": "मिश्र भिन्नों को साधारण भिन्न में बदलें: 9/4, 17/5, 3/2। क्रम से हल करने पर 5.1।", "level": "medium"}, {"s": "Mathematics", "t": "Mensuration", "q": "Find the curved surface area of a cylinder with base radius 14 cm and height 10 cm. (Take π = 22/7)", "o": ["880 cm²", "2112 cm²", "6160 cm²", "440 cm²"], "a": 0, "e": "CSA = 2πrh = 2 × 22/7 × 14 × 10 = 880 cm².", "qh": "14 cm आधार त्रिज्या और 10 cm ऊँचाई वाले बेलन का वक्र पृष्ठीय क्षेत्रफल बताइए। (π = 22/7 लें)", "oh": ["880 cm²", "2112 cm²", "6160 cm²", "440 cm²"], "eh": "वक्र पृष्ठीय क्षेत्रफल = 2πrh = 2 × 22/7 × 14 × 10 = 880 cm²।", "level": "tough"}, {"s": "Mathematics", "t": "Interest", "q": "What is the difference between the compound interest and simple interest on ₹21,000 for 2 years at 10% per annum (compounded annually)?", "o": ["₹420", "₹2,100", "₹210", "₹220"], "a": 2, "e": "For 2 years, CI − SI = P(R/100)² = ₹21,000 × (10/100)² = ₹210.", "qh": "₹21,000 पर 10% वार्षिक दर से 2 साल के चक्रवृद्धि ब्याज (वार्षिक) और साधारण ब्याज का अंतर क्या है?", "oh": ["₹420", "₹2,100", "₹210", "₹220"], "eh": "2 साल के लिए CI − SI = P(R/100)² = ₹21,000 × (10/100)² = ₹210।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "What is the remainder when 208 + 729 + 876 is divided by 9?", "o": ["3", "7", "6", "4"], "a": 3, "e": "Remainders: 1 + 0 + 3 = 4; 4 mod 9 = 4.", "qh": "208 + 729 + 876 को 9 से भाग देने पर शेषफल क्या होगा?", "oh": ["3", "7", "6", "4"], "eh": "शेषफल: 1 + 0 + 3 = 4; इसे 9 से भाग देने पर शेष 4।", "level": "easy"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "Two trains 280 m and 240 m long are running towards each other on parallel tracks at 45 km/h and 72 km/h. In how many seconds will they cross each other completely?", "o": ["13 seconds", "16 seconds", "20 seconds", "17 seconds"], "a": 1, "e": "Relative speed = 45 + 72 = 117 km/h = 32.5 m/s; distance = 520 m; time = 16 s.", "qh": "280 m और 240 m लंबी दो रेलगाड़ियाँ समांतर पटरियों पर एक-दूसरे की ओर 45 km/h और 72 km/h की चाल से आ रही हैं। वे कितने सेकंड में एक-दूसरे को पूरी तरह पार कर लेंगी?", "oh": ["13 सेकंड", "16 सेकंड", "20 सेकंड", "17 सेकंड"], "eh": "सापेक्ष चाल = 45 + 72 = 117 km/h = 32.5 m/s; दूरी = 520 m; समय = 16 सेकंड।", "level": "medium"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "A teacher found the average marks of 30 students to be 38. While checking, she noticed one student's marks were entered as 83 instead of 68. Find the correct average.", "o": ["37", "38", "38.5", "37.5"], "a": 3, "e": "Correct total = 30×38 − 83 + 68 = 1125; average = 37.5.", "qh": "एक शिक्षिका ने 30 छात्रों के औसत अंक 38 निकाले। जाँच में पता चला कि एक छात्र के अंक 68 की जगह 83 लिखे गए थे। सही औसत बताइए।", "oh": ["37", "38", "38.5", "37.5"], "eh": "सही योग = 30×38 − 83 + 68 = 1125; औसत = 37.5।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "Only two candidates contested a panchayat election. One received 60% of the valid votes and defeated the other by a margin of ₹1,400 votes. Find the total valid votes polled.", "o": ["₹14,000", "₹8,000", "₹7,000", "₹3,500"], "a": 2, "e": "Margin = 60% − 40% = 20% of total = ₹1,400 → total = ₹1,400 × 100/20 = ₹7,000.", "qh": "एक पंचायत चुनाव में केवल दो उम्मीदवार थे। एक को 60% वैध वोट मिले और उसने दूसरे को ₹1,400 वोटों के अंतर से हराया। कुल वैध वोट बताइए।", "oh": ["₹14,000", "₹8,000", "₹7,000", "₹3,500"], "eh": "अंतर = 60% − 40% = कुल का 20% = ₹1,400 → कुल = ₹1,400 × 100/20 = ₹7,000।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Deepak bought an old scooter for ₹18,500 and spent ₹1,300 on repairs. He sold it for ₹23,760. What is his profit percentage?", "o": ["28 16/37%", "25%", "21 15/37%", "20%"], "a": 3, "e": "Total CP = ₹18,500 + ₹1,300 = ₹19,800; profit = ₹3,960; profit % = ₹3,960/₹19,800 × 100 = 20%.", "qh": "दीपक ने एक पुराना स्कूटर ₹18,500 में खरीदा और ₹1,300 मरम्मत पर खर्च किए। उसने इसे ₹23,760 में बेचा। उसका लाभ प्रतिशत क्या है?", "oh": ["28 16/37%", "25%", "21 15/37%", "20%"], "eh": "कुल क्रय मूल्य = ₹18,500 + ₹1,300 = ₹19,800; लाभ = ₹3,960; लाभ % = ₹3,960/₹19,800 × 100 = 20%।", "level": "easy"}, {"s": "Mathematics", "t": "Ages", "q": "The present ages of Geeta and Kavita are in the ratio 5 : 6. After 6 years, the ratio will be 31 : 36. What is Kavita's present age?", "o": ["36 years", "30 years", "24 years", "25 years"], "a": 1, "e": "(5x + 6)/(6x + 6) = 31/36 → x = 5; age = 6 × 5 = 30 years.", "qh": "गीता और कविता की अभी की आयु का अनुपात 5 : 6 है। 6 साल बाद यह अनुपात 31 : 36 हो जाएगा। कविता की अभी की आयु कितनी है?", "oh": ["36 साल", "30 साल", "24 साल", "25 साल"], "eh": "(5x + 6)/(6x + 6) = 31/36 → x = 5; आयु = 6 × 5 = 30 साल।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\nA 6 * % % R B 4 * 1 2 € A # 3 A N Q O 5 Q 6\nHow many numbers are there in the arrangement, each of which is immediately preceded by a letter and immediately followed by a symbol?", "o": ["4", "2", "3", "5"], "a": 1, "e": "Matching places: A6*, B4* → 2.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\nA 6 * % % R B 4 * 1 2 € A # 3 A N Q O 5 Q 6\nइस क्रम में ऐसी कितनी संख्याएँ हैं, जिनके ठीक पहले एक अक्षर और ठीक बाद एक चिह्न है?", "oh": ["4", "2", "3", "5"], "eh": "शर्त पूरी करने वाले स्थान: A6*, B4* → 2।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n3 2 8 8 3 1 2 3 6 1 1 4 8 2 2 3 3 5 8 2 4 3 7 5 7\nHow many 5s are there, each of which is immediately preceded by an odd digit and immediately followed by an even digit?", "o": ["3", "4", "2", "1"], "a": 3, "e": "Matching groups: 3 5 8 → 1.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n3 2 8 8 3 1 2 3 6 1 1 4 8 2 2 3 3 5 8 2 4 3 7 5 7\nऐसे कितने 5 हैं, जिनके ठीक पहले विषम अंक और ठीक बाद सम अंक है?", "oh": ["3", "4", "2", "1"], "eh": "शर्त पूरी करने वाले समूह: 3 5 8 → 1।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["BFJL", "MRVX", "NRVX", "KOSU"], "a": 1, "e": "In BFJL, NRVX, KOSU the gaps are +4, +4, +2; in MRVX they are +5, +4, +2.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["BFJL", "MRVX", "NRVX", "KOSU"], "eh": "BFJL, NRVX, KOSU में अंतर +4, +4, +2 है; MRVX में +5, +4, +2 है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "L, K, E, A, W, B, C and F are sitting around a circular table, all facing the centre.\nW sits second to the left of L.\nL sits immediately to the right of B.\nF sits immediately to the left of C.\nE is not an immediate neighbour of C.\nE sits opposite L.\nA sits second to the left of B.\nWho sits to the immediate right of E?", "o": ["A", "W", "F", "C"], "a": 0, "e": "Only one arrangement fits. Going to the right (anticlockwise) from E: E → A → W → B → L → F → C → K. Answer: A.", "qh": "L, K, E, A, W, B, C और F एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nW, L के बाईं ओर दूसरे स्थान पर बैठा है।\nL, B के ठीक दाईं ओर बैठा है।\nF, C के ठीक बाईं ओर बैठा है।\nE, C का ठीक पड़ोसी नहीं है।\nE, L के ठीक सामने बैठा है।\nA, B के बाईं ओर दूसरे स्थान पर बैठा है।\nE के ठीक दाईं ओर कौन बैठा है?", "oh": ["A", "W", "F", "C"], "eh": "केवल एक व्यवस्था बैठती है। E से दाईं ओर (घड़ी की उलटी दिशा में) चलें: E → A → W → B → L → F → C → K। उत्तर: A।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Water Image", "q": "Which of the following words will look exactly the same in its water image (reflection in water)? (The letters are written in capital letters.)", "o": ["WATCH", "HOT", "DECIDE", "YOUTH"], "a": 2, "e": "In water, the image is flipped top-to-bottom; letters B, C, D, E, H, I, K, O, X stay the same. Every letter of DECIDE is from this group.", "qh": "नीचे दिए शब्दों में से कौन-सा शब्द अपनी पानी में परछाईं (जल प्रतिबिंब) में बिल्कुल वैसा ही दिखेगा? (अक्षर बड़े अंग्रेज़ी अक्षरों में लिखे हैं।)", "oh": ["WATCH", "HOT", "DECIDE", "YOUTH"], "eh": "पानी में प्रतिबिंब ऊपर-नीचे पलटता है; B, C, D, E, H, I, K, O, X वैसे ही रहते हैं। DECIDE के सारे अक्षर इसी समूह के हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Calendar and Clock", "q": "If 8 February 2022 was a Tuesday, what day of the week was 7 April 2022?", "o": ["Thursday", "Friday", "Wednesday", "Saturday"], "a": 0, "e": "Days from 8 February 2022 to 7 April 2022 = 58. 58 = 7 × 8 + 2 → 2 odd day(s) after Tuesday = Thursday.", "qh": "अगर 8 फ़रवरी 2022 को मंगलवार था, तो 7 अप्रैल 2022 को कौन-सा दिन था?", "oh": ["गुरुवार", "शुक्रवार", "बुधवार", "शनिवार"], "eh": "8 फ़रवरी 2022 से 7 अप्रैल 2022 तक दिन = 58। 58 = 7 × 8 + 2 → मंगलवार के 2 दिन बाद = गुरुवार।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language:\n'very sky book' is written as 'ze ta pu',\n'long very green' is written as 'ra dy ze',\n'sky road long' is written as 'dy ki pu',\nWhat is the code for 'very'?", "o": ["pu", "ze", "ta", "dy"], "a": 1, "e": "Compare the sentences: common words and common codes match. This gives 'very' = 'ze'.", "qh": "एक कोड भाषा में:\n'very sky book' को 'ze ta pu' लिखा जाता है,\n'long very green' को 'ra dy ze' लिखा जाता है,\n'sky road long' को 'dy ki pu' लिखा जाता है,\n'very' का कोड क्या है?", "oh": ["pu", "ze", "ta", "dy"], "eh": "वाक्यों की तुलना करें: साझा शब्द और साझा कोड आपस में मिलते हैं। इससे 'very' = 'ze' मिलता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nVVO : WUQ :: JHO : ?", "o": ["QGK", "KGQ", "IIM", "KGR"], "a": 1, "e": "Each letter moves +1, -1, +2 in order. JHO → KGQ.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nVVO : WUQ :: JHO : ?", "oh": ["QGK", "KGQ", "IIM", "KGR"], "eh": "हर अक्षर क्रम से +1, -1, +2 खिसकता है। JHO → KGQ।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n12 : 252 :: 13 : ?", "o": ["169", "390", "403", "416"], "a": 2, "e": "Rule: x → x × (x with digits reversed). 12 → 252, so 13 → 403.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n12 : 252 :: 13 : ?", "oh": ["169", "390", "403", "416"], "eh": "नियम: x → x × (x के अंक उलटे)। 12 → 252, इसलिए 13 → 403।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a row of 33 children, Ravi is 17th from the left and Deepak is 9th from the right. When Ravi shifts 4 places towards the right, what is his position from the right end?", "o": ["14", "13", "15", "12"], "a": 1, "e": "New position from left = 17 + 4 = 21; from right = 33 − 21 + 1 = 13.", "qh": "33 बच्चों की पंक्ति में रवि बाएँ से 17वें और दीपक दाएँ से 9वें स्थान पर है। रवि के 4 स्थान दाईं ओर खिसकने पर वह दाएँ छोर से किस स्थान पर होगा?", "oh": ["14", "13", "15", "12"], "eh": "बाएँ से नया स्थान = 17 + 4 = 21; दाएँ से = 33 − 21 + 1 = 13।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["Wheat", "Mustard", "Rice", "Maize"], "a": 1, "e": "Mustard is an oilseed; the others are cereals.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["गेहूँ", "सरसों", "चावल", "मक्का"], "eh": "सरसों तिलहन है; बाकी अनाज हैं।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '÷', '−' means '+', '×' means '−', '÷' means '×', then what is the value of the following expression?\n28 ÷ 20 × 12 ÷ 21 = ?", "o": ["305", "318", "308", "310"], "a": 2, "e": "Replace the signs: 28 × 20 − 12 × 21 = 308 (using BODMAS).", "qh": "अगर '+' का मतलब '÷', '−' का मतलब '+', '×' का मतलब '−', '÷' का मतलब '×' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n28 ÷ 20 × 12 ÷ 21 = ?", "oh": ["305", "318", "308", "310"], "eh": "चिह्न बदलें: 28 × 20 − 12 × 21 = 308 (BODMAS से)।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Manoj starts from point P, walks 6 km towards North, then turns right and walks 10 km, then turns right and walks 12 km. In which direction is Manoj now with respect to point P?", "o": ["North-West", "South-East", "North-East", "West"], "a": 1, "e": "Net East–West = +10 km, net North–South = -6 km; direction = South-East.", "qh": "मनोज बिंदु P से शुरू करके उत्तर की ओर 6 km चलता है, फिर दाएँ मुड़कर 10 km चलता है, फिर दाएँ मुड़कर 12 km चलता है। अब मनोज बिंदु P से किस दिशा में है?", "oh": ["उत्तर-पश्चिम", "दक्षिण-पूर्व", "उत्तर-पूर्व", "पश्चिम"], "eh": "कुल पूर्व–पश्चिम = +10 km, कुल उत्तर–दक्षिण = -6 km; दिशा = दक्षिण-पूर्व।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n$ 2 + 3 $ 6 % 4 @ % R © 2 1 S 3 $ R\nHow many symbols are there in the arrangement, each of which is immediately preceded by a number?", "o": ["6", "8", "4", "5"], "a": 3, "e": "Matching places: 2+3, 3$6, 6%4, 4@%, 3$R → 5.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n$ 2 + 3 $ 6 % 4 @ % R © 2 1 S 3 $ R\nइस क्रम में ऐसे कितने चिह्न हैं, जिनके ठीक पहले एक संख्या है?", "oh": ["6", "8", "4", "5"], "eh": "शर्त पूरी करने वाले स्थान: 2+3, 3$6, 6%4, 4@%, 3$R → 5।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "V is the father of N. N is the mother of H. How is V related to H?", "o": ["Brother-in-law", "Husband", "Father", "Grandfather"], "a": 3, "e": "Draw the family tree: V → N: father; N → H: mother. So V is the grandfather of H.", "qh": "V, N का पिता है। N, H की माँ है। V का H से क्या संबंध है?", "oh": ["साला/देवर/जीजा", "पति", "पिता", "दादा/नाना"], "eh": "परिवार का चार्ट बनाएँ: V → N: पिता; N → H: माँ। इसलिए V, H का दादा/नाना है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "T is the father of E. E is the daughter of D. How is T related to D?", "o": ["Husband", "Father-in-law", "Uncle", "Nephew"], "a": 0, "e": "Draw the family tree: T → E: father; E → D: daughter. So T is the husband of D.", "qh": "T, E का पिता है। E, D की बेटी है। T का D से क्या संबंध है?", "oh": ["पति", "ससुर", "चाचा/मामा", "भतीजा/भांजा"], "eh": "परिवार का चार्ट बनाएँ: T → E: पिता; E → D: बेटी। इसलिए T, D का पति है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "M, V, T, F, D, B and S are sitting in a row, all facing North.\nV sits at one of the ends.\nExactly 1 person sits between S and F.\nExactly 2 persons sit between M and D.\nF sits second to the right of S.\nD sits second to the right of T.\nExactly 1 person sits between M and S.\nExactly 3 persons sit between V and T.\nWho sits exactly in the middle of the row?", "o": ["F", "V", "D", "S"], "a": 3, "e": "Only one order fits all clues (left to right): B M T S D F V. Answer: S.", "qh": "M, V, T, F, D, B और S एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nV किसी एक छोर पर बैठा है।\nS और F के बीच ठीक 1 व्यक्ति बैठे हैं।\nM और D के बीच ठीक 2 व्यक्ति बैठे हैं।\nF, S के दाईं ओर दूसरे स्थान पर बैठा है।\nD, T के दाईं ओर दूसरे स्थान पर बैठा है।\nM और S के बीच ठीक 1 व्यक्ति बैठे हैं।\nV और T के बीच ठीक 3 व्यक्ति बैठे हैं।\nपंक्ति के ठीक बीच में कौन बैठा है?", "oh": ["F", "V", "D", "S"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): B M T S D F V। उत्तर: S।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nNo trees are books.\nAll books are bags.\nConclusions:\nI. Some bags are not books.\nII. Some books are bags.", "o": ["Neither I nor II follows", "Only conclusion II follows", "Only conclusion I follows", "Both I and II follow"], "a": 1, "e": "Conclusion II is true in every possible diagram; I is not.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकोई भी पेड़ किताबें नहीं है।\nसभी किताबें थैले हैं।\nनिष्कर्ष:\nI. कुछ थैले किताबें नहीं हैं।\nII. कुछ किताबें थैले हैं।", "oh": ["न I सही है, न II", "केवल निष्कर्ष II सही है", "केवल निष्कर्ष I सही है", "I और II दोनों सही हैं"], "eh": "निष्कर्ष II हर संभव आरेख में सही है; I नहीं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n18, 20, 24, 32, 48, 80, ?", "o": ["147", "146", "140", "144"], "a": 3, "e": "Rule: Differences are 2, 4, 8, 16, 32, 64 (×2 each time). So ? = 144.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n18, 20, 24, 32, 48, 80, ?", "oh": ["147", "146", "140", "144"], "eh": "नियम: अंतर 2, 4, 8, 16, 32, 64 हैं (हर बार ×2)। इसलिए ? = 144।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nBird : Nest :: Bee : ?", "o": ["Honey", "Flower", "Sting", "Hive"], "a": 3, "e": "Relation: 'lives in'. Bird – Nest, so Bee – Hive.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nपक्षी : घोंसला :: मधुमक्खी : ?", "oh": ["शहद", "फूल", "डंक", "छत्ता"], "eh": "संबंध: 'में रहता है'। पक्षी – घोंसला, इसलिए मधुमक्खी – छत्ता।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nG6Z, K12W, O24T, S48Q, ?", "o": ["W96N", "W96O", "W95N", "X96N"], "a": 0, "e": "First letter +4; number: double each time; last letter -3. So ? = W96N.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nG6Z, K12W, O24T, S48Q, ?", "oh": ["W96N", "W96O", "W95N", "X96N"], "eh": "पहला अक्षर +4; संख्या: हर बार दोगुना; आखिरी अक्षर -3। इसलिए ? = W96N।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n739   712   238   423   724\nIf 1 is added to each digit of every number (9 becomes 0), how many of the new numbers will be even?", "o": ["2", "3", "5", "0"], "a": 0, "e": "New numbers: 840, 823, 349, 534, 835 → even ones = 2.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n739   712   238   423   724\nअगर हर संख्या के हर अंक में 1 जोड़ा जाए (9 का 0 हो जाए), तो नई संख्याओं में से कितनी सम होंगी?", "oh": ["2", "3", "5", "0"], "eh": "नई संख्याएँ: 840, 823, 349, 534, 835 → सम संख्याएँ = 2।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'BRICK' is written as 'ZPGAI'. How will 'LIGHT' be written in that language?", "o": ["JGFFR", "RFEGJ", "JGEFR", "JGEFQ"], "a": 2, "e": "Rule: each letter moves -2. Applying it to LIGHT gives JGEFR.", "qh": "एक कोड भाषा में 'BRICK' को 'ZPGAI' लिखा जाता है। उसी भाषा में 'LIGHT' को कैसे लिखा जाएगा?", "oh": ["JGFFR", "RFEGJ", "JGEFR", "JGEFQ"], "eh": "नियम: हर अक्षर -2 खिसकता है। LIGHT पर लगाने से JGEFR मिलता है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "Which two mathematical signs should be interchanged to make the following equation correct?\n9 − 16 ÷ 3 + 8 × 8 = 48", "o": ["− and ×", "+ and −", "− and ÷", "+ and ÷"], "a": 0, "e": "Interchanging − and ×: 9 × 16 ÷ 3 + 8 − 8 = 48. ✔", "qh": "नीचे दिए समीकरण को सही बनाने के लिए किन दो गणितीय चिह्नों को आपस में बदलना होगा?\n9 − 16 ÷ 3 + 8 × 8 = 48", "oh": ["− और ×", "+ और −", "− और ÷", "+ और ÷"], "eh": "− और × बदलने पर: 9 × 16 ÷ 3 + 8 − 8 = 48। ✔", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nYLK, CPL, GTM, KXN, ?", "o": ["OBP", "OCO", "OBN", "OBO"], "a": 3, "e": "Letter positions move by +4, +4, +1 (for 1st, 2nd, 3rd letters). So ? = OBO.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nYLK, CPL, GTM, KXN, ?", "oh": ["OBP", "OCO", "OBN", "OBO"], "eh": "अक्षरों की स्थिति +4, +4, +1 से बदलती है (पहले, दूसरे, तीसरे अक्षर के लिए)। इसलिए ? = OBO।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Data Sufficiency", "q": "Question: What is the present age of Karan?\nStatement I: Karan will be 25 years old after 5 years.\nStatement II: Karan was 18 years old two years ago.\nWhich of the following is correct?", "o": ["The data in either statement I alone or statement II alone is sufficient", "The data in both statements together is not sufficient", "The data in statement II alone is sufficient", "The data in statement I alone is sufficient"], "a": 0, "e": "Each statement alone gives the age.", "qh": "प्रश्न: करण की अभी की आयु क्या है?\nकथन I: 5 साल बाद करण की आयु 25 साल होगी।\nकथन II: दो साल पहले करण की आयु 18 साल थी।\nनीचे दिए विकल्पों में से कौन-सा सही है?", "oh": ["अकेले कथन I या अकेले कथन II, कोई भी काफ़ी है", "दोनों कथन मिलकर भी काफ़ी नहीं हैं", "केवल कथन II का आँकड़ा काफ़ी है", "केवल कथन I का आँकड़ा काफ़ी है"], "eh": "हर कथन अकेले ही आयु बता देता है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["218", "729", "1000", "27"], "a": 0, "e": "All except 218 are perfect cubes.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["218", "729", "1000", "27"], "eh": "218 को छोड़कर सभी पूर्ण घन हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Statement and Conclusion", "q": "Read the statement and the conclusions/assumptions given below and decide which of them logically follow(s).\nStatement: Only those who have a valid ticket are allowed on the platform.\nConclusions:\nI. A person without a valid ticket may not enter the platform.\nII. Everyone with a valid ticket must enter the platform.", "o": ["Only conclusion II follows", "Both I and II follow", "Neither I nor II follows", "Only conclusion I follows"], "a": 3, "e": "'Only ticket-holders are allowed' directly gives I. Being allowed is not being forced, so II does not follow.", "qh": "नीचे दिए कथन और निष्कर्ष/धारणाएँ पढ़कर तय कीजिए कि कौन-सा/से तर्क के आधार पर सही है/हैं।\nकथन: केवल वैध टिकट वालों को ही प्लेटफ़ॉर्म पर जाने की अनुमति है।\nनिष्कर्ष:\nI. बिना वैध टिकट वाला व्यक्ति प्लेटफ़ॉर्म पर नहीं जा सकता।\nII. वैध टिकट वाले हर व्यक्ति को प्लेटफ़ॉर्म पर जाना ही होगा।", "oh": ["केवल निष्कर्ष II सही है", "I और II दोनों सही हैं", "न I सही है, न II", "केवल निष्कर्ष I सही है"], "eh": "'केवल टिकट वाले' से सीधे I निकलता है। अनुमति का मतलब मजबूरी नहीं, इसलिए II नहीं।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n12, 17, 9, 14, 6, 11, ?", "o": ["4", "5", "3", "8"], "a": 2, "e": "Rule: Alternately +5 and −8. So ? = 3.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n12, 17, 9, 14, 6, 11, ?", "oh": ["4", "5", "3", "8"], "eh": "नियम: बारी-बारी से +5 और −8। इसलिए ? = 3।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Rohit starts from point P, walks 8 km towards West, then turns right and walks 12 km, then turns left and walks 4 km. In which direction is Rohit now with respect to point P?", "o": ["South-East", "South-West", "North-West", "East"], "a": 2, "e": "Net East–West = -12 km, net North–South = +12 km; direction = North-West.", "qh": "रोहित बिंदु P से शुरू करके पश्चिम की ओर 8 km चलता है, फिर दाएँ मुड़कर 12 km चलता है, फिर बाएँ मुड़कर 4 km चलता है। अब रोहित बिंदु P से किस दिशा में है?", "oh": ["दक्षिण-पूर्व", "दक्षिण-पश्चिम", "उत्तर-पश्चिम", "पूर्व"], "eh": "कुल पूर्व–पश्चिम = -12 km, कुल उत्तर–दक्षिण = +12 km; दिशा = उत्तर-पश्चिम।", "level": "easy"}]});
